// Turns the Better Auth CLI output into src/server/db/schema/auth.ts:
// every timestamp becomes timestamptz and a provenance header is added.
import { readFileSync, rmSync, writeFileSync } from "node:fs";

const dir = new URL("../src/server/db/schema/", import.meta.url);
const generated = new URL("auth.generated.ts", dir);

const header = `/**
 * Better Auth tables — GENERATED by \`pnpm auth:generate\` (scripts/auth-cli.config.ts),
 * then post-processed by \`scripts/postprocess-auth-schema.mjs\` to make every
 * timestamp \`timestamptz\`. Do not hand-edit; change shared-options.ts and regenerate.
 */
`;

const source = readFileSync(generated, "utf8").replace(
  /timestamp\("([a-z_]+)"\)/g,
  'timestamp("$1", { withTimezone: true })',
);

writeFileSync(new URL("auth.ts", dir), header + source);
rmSync(generated);
console.log("Wrote src/server/db/schema/auth.ts");
